-Math.pow(1-p,3));\n          var s=dec?v.toFixed(dec):String(Math.round(v));if(!dec&&m[2].indexOf(\',\')>-1)s=Math.round(v).toLocaleString(\'en-IN\');el.textContent=m[1]+s+m[3];\n          if(p<1)requestAnimationFrame(step);\n        }\n        requestAnimationFrame(step);\n      });\n    },{threshold:.4});\n    nums.forEach(function(n){no.observe(n)});\n  });\n})();\n</script>\n\n<script>\n(function(){\n  var wrap=document.querySelector(\'.hasmega\');\n  if(!wrap) return;\n  var panel=wrap.parentElement.querySelector(\'.mega\')||document.querySelector(\'.mega\');\n  var t=null;\n  function open(){ clearTimeout(t); wrap.classList.add(\'open\'); }\n  function close(){ clearTimeout(t); t=setTimeout(function(){ wrap.classList.remove(\'open\'); },320); }\n  [wrap,panel].forEach(function(el){\n    if(!el) return;\n    el.addEventListener(\'mouseenter\',open);\n    el.addEventListener(\'mouseleave\',close);\n    el.addEventListener(\'focusin\',open);\n  });\n  document.addEventListener(\'keydown\',function(e){ if(e.key===\'Escape\') wrap.classList.remove(\'open\'); });\n})();\n</script>\n</body>\n</html>','2026-09-09 16:51:02','2026-09-09 16:51:02','2026-09-09 16:51:02'),(10,'contact-us','contact-us.php','published','Contact Us | Free AV Design and Pricing in 24 Hours | Bitsy AV','Call +91 99303 73731, WhatsApp us or send your brief. A Certified Technology Specialist replies within 24 working hours with a layout and an honest budget.','Contact Us | Free AV Design and Pricing in 24 Hours | Bitsy AV','Call +91 99303 73731, WhatsApp us or send your brief. A Certified Technology Specialist replies within 24 working hours with a layout and an honest budget.','Send the brief. Get a design and a number.','Ninety seconds of detail is all a Certified Technology Specialist needs to come back with a layout, a spec sheet and an honest budget, free.','<?php require_once __DIR__ . \'/includes/site-bootstrap.php\'; ?>\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\