\'(prefers-reduced-motion: reduce)\').matches||!(\'IntersectionObserver\'in window))return;\n  root.classList.add(\'anim\');\n  var sel=\'.sec .kicker,.sec > .wrap > h2,.sec > .wrap > .lede,.card,.quotes blockquote,.grid3 > *,.grid4 > *,.logogrid .clientcard,.panel,.ctaband,.finalcta,.magnet,.statband .g > div,.factgrid > div,.steps li,.deftable,.faqs details,.washed,.formcard.plain\';\n  var io=new IntersectionObserver(function(es){\n    es.forEach(function(e){\n      if(!e.isIntersecting)return;\n      var el=e.target;\n      el.style.setProperty(\'--d\',(el.__i||0)*55+\'ms\');\n      el.classList.add(\'in\');\n      io.unobserve(el);\n    });\n  },{rootMargin:\'0px 0px -8% 0px\',threshold:.06});\n  requestAnimationFrame(function(){\n    document.querySelectorAll(sel).forEach(function(el){\n      if(el.closest(\'.hero\')||el.closest(\'.hdr\')||el.closest(\'.pagehero\'))return;\n      el.classList.add(\'rise\');\n      var p=el.parentElement, i=0, k=p?p.children:[];\n      for(var j=0;j<k.length;j++){ if(k[j]===el){ i=Math.min(j,5); break; } }\n      el.__i=i;\n      io.observe(el);\n    });\n    var nums=document.querySelectorAll(\'.statband b,.factgrid b,.herostats b\');\n    var no=new IntersectionObserver(function(es){\n      es.forEach(function(e){\n        if(!e.isIntersecting)return;\n        var el=e.target, txt=el.textContent, m=txt.match(/^(\\D*)(\\d[\\d,.]*)(.*)$/);\n        no.unobserve(el);\n        if(!m)return;\n        var target=parseFloat(m[2].replace(/,/g,\'\')), dec=(m[2].split(\'.\')[1]||\'\').length, t0=null;\n        function step(ts){\n          if(!t0)t0=ts;\n          var p=Math.min((ts-t0)/900,1), v=target*(1-Math.pow(1-p,3));\n          var s=dec?v.toFixed(dec):String(Math.round(v));if(!dec&&m[2].indexOf(\',\')>-1)s=Math.round(v).toLocaleString(\'en-IN\');el.textContent=m[1]+s+m[3];\n          if(p<1)requestAnimationFrame(step);\n        }\n        requestAnimationFrame(step);\n      });\n    },{threshold:.4});\n    nums.forEach(function(n){no.observe(n)});\n  });\n})();\n</script>\n\n<script>\n(function(){\n  var wrap=document.querySelector(\'.hasmega\');\n  if(!wrap) return;\n  var panel=wrap.parentElement.querySelector(\'.mega\')||document.querySelector(\'.mega\');\n  var t=null;\n  function open(){ clearTimeout(t); wrap.classList.add(\'open\'); }\n  function close(){ clearTimeout(t); t=setTimeout(function(){ wrap.classList.remove(\'open\'); },320); }\n  [wrap,panel].forEach(function(el){\n    if(!el) return;\n    el.addEventListener(\'mouseenter\',open);\n    el.addEventListener(\'mouseleave\',close);\n    el.addEventListener(\'focusin\',open);\n  });\n  document.addEventListener(\'keydown\',function(e){ if(e.key===\'Escape\') wrap.classList.remove(\'open\'); });\n})();\n</script>\n</body>\n</html>','2026-09-09 16:51:02','2026-09-09 16:51:02','2026-09-09 16:51:02'),(25,'wayfinding-kiosk','wayfinding-kiosk.php','published','Interactive Wayfinding Kiosks | Free Design and Pricing in 24 Hours | Bitsy AV','Interactive wayfinding kiosk design and supply for malls, hospitals, campuses and transport hubs.','Interactive Wayfinding Kiosks | Free Design and Pricing in 24 Hours | Bitsy AV','Interactive wayfinding kiosk design and supply for malls, hospitals, campuses and transport hubs.','Wayfinding that answers the question in one tap','Mapped, searchable directories for campuses, malls, hospitals and transport hubs.','<?php require_once __DIR__ . \'/includes/site-bootstrap.php\'; ?>\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Interactive Wayfinding Kiosks | Free Design and Pricing in 24 Hours | Bitsy AV</title>\n<meta name=\"description\" content=\"Interactive wayfinding kiosk design and supply for malls, hospitals, campuses and transport hubs.\">\n<meta property=\"og:title\" content=\"Interactive Wayfinding Kiosks | Free Design and Pricing in 24 Hours | Bitsy AV\">\n<meta property=\"og:descripti